EnumerateCsv                   00:00:02.9947520
</code></pre>

Q: Setting newtab.location.href fails to redirect a different tab A: <p>The main issue is the SECOND change of location which will give an access error.</p>
<p>You are not allowed to load a page not from your origin using script and then replace that window location with another page not from your origin</p>
<p>Here is an attempt to fix that. It will not run at SO but will run on JSFiddle</p>
<p><a href="https://jsfiddle.net/mplungjan/syfrkb36/" rel="nofollow noreferrer">https://jsfiddle.net/mplungjan/syfrkb36/</a></p>
<p>However I have not yet made it work in ONE window. It will open a new window for each search.</p>
<p>I am on version 5: <a href="https://jsfiddle.net/mplungjan/syfrkb36/5" rel="nofollow noreferrer">https://jsfiddle.net/mplungjan/syfrkb36/5</a></p>
<pre class="lang-js prettyprint-override"><code>// Fisher-Yates
const shuffle = arr =&gt; {
  for (let i = arr.length - 1; i &gt; 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [arr[i], arr[j]] = [arr[j], arr[i]];
  }
  return arr;
};

// shuffle once, then walk through
const pool = shuffle([...words]);
let idx = 0;
let intervalId = null;

const nextQuery = () =&gt; {
  if (idx &gt;= pool.length - 2) {
    return null; // less than 3 words left
  }
  const w1 = pool[idx++];
  const w2 = pool[idx++];
  const w3 = pool[idx++];
  return encodeURIComponent(`${w1} ${w2} ${w3}`);
};

const randomSearch = () =&gt; {
  const q = nextQuery();
  if (!q) {
    clearInterval(intervalId);
    intervalId = null;
    return;
  }
  const href = 'https://www.google.com/search?q=' + q;

  // use a fixed window name so the same tab is reused
  window.open(href, 'RandomGoogleSearch');
};

// call this from a click handler to avoid popup blocking
document.getElementById('start').addEventListener('click',() =&gt; {
  if (intervalId) return; // already running
  randomSearch(); // fire first search immediately
  intervalId = setInterval(randomSearch, 7500);
});
</code></pre>
